import type { Metadata } from "next";
import Link from "next/link";
import { Wordmark } from "@/components/brand/Wordmark";
import { pageMetadata } from "@/lib/site";
// Generated by backend/scripts/attribution/build_sources.py from the source
// manifests; never edit by hand. Every license, attribution and citation
// string below comes from it.
import data from "@/data/sources.generated.json";

export const metadata: Metadata = pageMetadata({
  title: "Sources",
  description:
    "The open dictionaries and wordnets NameLeaf is built from, with their authors, licenses and the full license texts they require.",
  path: "/sources",
});

type Source = (typeof data.sources)[number];

const languageNames = new Intl.DisplayNames(["en"], { type: "language" });

function languageName(code: string): string {
  try {
    return languageNames.of(code) ?? code;
  } catch {
    return code;
  }
}

function ExternalLink({ href, children }: { href: string; children: React.ReactNode }) {
  return (
    <a
      href={href}
      className="underline decoration-slate-300 underline-offset-2 hover:decoration-slate-600"
      rel="noopener noreferrer"
    >
      {children}
    </a>
  );
}

function LicenseLink({ source }: { source: Source }) {
  if (source.licenseTextId) {
    return (
      <a
        href={`#license-${source.licenseTextId}`}
        className="underline decoration-slate-300 underline-offset-2 hover:decoration-slate-600"
      >
        {source.license}
      </a>
    );
  }
  if (source.licenseUrl) {
    return <ExternalLink href={source.licenseUrl}>{source.license}</ExternalLink>;
  }
  return <>{source.license}</>;
}

function SourceCard({ source }: { source: Source }) {
  const languages = source.languageCodes
    .map(languageName)
    .sort((a, b) => a.localeCompare(b, "en"))
    .join(", ");
  return (
    <article className="rounded-2xl border border-slate-200 bg-white p-5">
      <h3 className="font-semibold">
        {source.homepage ? (
          <ExternalLink href={source.homepage}>{source.name}</ExternalLink>
        ) : (
          source.name
        )}
      </h3>
      {source.upstream && source.upstreamUrl && (
        <p className="mt-2 text-sm leading-6 text-slate-700">
          From <ExternalLink href={source.upstreamUrl}>Wiktionary</ExternalLink>, by its
          contributors; extracted by{" "}
          {source.homepage ? (
            <ExternalLink href={source.homepage}>Kaikki.org</ExternalLink>
          ) : (
            "Kaikki.org"
          )}
          .
        </p>
      )}
      {languages && (
        <p className="mt-2 text-sm text-slate-500">Languages: {languages}</p>
      )}
      <p className="mt-2 text-sm leading-6 text-slate-700">{source.attribution}</p>
      <p className="mt-2 text-sm text-slate-700">
        License: <LicenseLink source={source} />
      </p>
      <p className="mt-2 text-sm text-slate-500">Modified by NameLeaf.</p>
    </article>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="mt-12">
      <h2 className="text-xl font-bold tracking-tight">{title}</h2>
      <div className="mt-4 grid gap-4">{children}</div>
    </section>
  );
}

export default function SourcesPage() {
  const bySection = (section: string) =>
    data.sources.filter((source) => source.section === section);
  const licensed = (id: string) => data.sources.find((s) => s.slug === id);

  return (
    <main className="min-h-screen bg-stone-50">
      <header className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex max-w-4xl items-center justify-between px-4 py-5 sm:px-6">
          <Link href="/" className="inline-flex min-h-11 items-center">
            <Wordmark />
          </Link>
        </div>
      </header>

      <div className="mx-auto max-w-4xl px-4 py-12 sm:px-6">
        <h1 className="text-3xl font-bold tracking-tight">Sources</h1>
        <p className="mt-4 max-w-3xl text-base leading-7 text-slate-600">
          NameLeaf is built from the open sources below. Each one has been imported,
          filtered, combined with the others and indexed for search, so what you see on
          NameLeaf is modified from the original data.
        </p>

        <Section title="Dictionary data">
          {bySection("dictionary").map((source) => (
            <SourceCard key={source.slug} source={source} />
          ))}
        </Section>

        <Section title="Wordnets">
          {bySection("wordnet").map((source) => (
            <SourceCard key={source.slug} source={source} />
          ))}
        </Section>

        <Section title="Machine-generated data">
          <p className="text-sm leading-6 text-slate-700">
            Origin labels on English-labelled names were resolved partly by Google
            Gemini, from each name and its meaning as recorded in Wiktionary.
          </p>
          {bySection("machine").map((source) => (
            <SourceCard key={source.slug} source={source} />
          ))}
        </Section>

        <Section title="Model">
          <p className="text-sm leading-6 text-slate-700">
            Search compares meanings with this embedding model.
          </p>
          {data.models.map((model) => (
            <article
              key={model.name}
              className="min-w-0 rounded-2xl border border-slate-200 bg-white p-5"
            >
              <h3 className="break-words font-semibold">{model.name}</h3>
              <p className="mt-2 break-all text-sm text-slate-500">Revision {model.revision}</p>
              <pre className="mt-3 overflow-x-auto whitespace-pre-wrap rounded-lg bg-slate-50 p-3 text-xs leading-5 text-slate-700">
                {model.citation}
              </pre>
              <p className="mt-2 text-sm text-slate-700">License: {model.license}</p>
            </article>
          ))}
        </Section>

        <Section title="License texts">
          <p className="text-sm leading-6 text-slate-700">
            These wordnets are distributed under licenses that ask for their full text,
            including the copyright notice and disclaimer, to accompany the data. Each is
            reproduced in full.
          </p>
          {data.licenseTexts.map((text) => (
            <details
              key={text.id}
              id={`license-${text.id}`}
              className="rounded-2xl border border-slate-200 bg-white p-5"
            >
              <summary className="cursor-pointer font-semibold">
                {licensed(text.appliesTo)?.name ?? text.appliesTo}
              </summary>
              <pre className="mt-3 overflow-x-auto whitespace-pre-wrap text-xs leading-5 text-slate-700">
                {text.text}
              </pre>
            </details>
          ))}
        </Section>

        <section className="mt-12 border-t border-slate-200 pt-6">
          <p className="text-sm text-slate-600">
            Spotted a missing or wrong credit?{" "}
            <a
              href="mailto:contact@nameleaf.app"
              className="underline decoration-slate-300 underline-offset-2 hover:decoration-slate-600"
            >
              contact@nameleaf.app
            </a>
          </p>
        </section>
      </div>
    </main>
  );
}
